/**
 * TimeSlotList Service Implementation
 * Manages time slot fetching, selection, and state
 */
import { implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { TimeSlotListServiceDefinition, ViewMode, } from './time-slot-list.def.js';
import { LocationType, } from '@wix/auto_sdk_bookings_availability-time-slots';
import { fetchAvailability } from '../../api/fetch-availability/index.js';
import { BookingServiceDefinition, } from '../booking/booking.js';
// ============================================================================
// Helpers
// ============================================================================
const getClientTimezone = () => {
    return typeof Intl !== 'undefined'
        ? Intl.DateTimeFormat().resolvedOptions().timeZone
        : undefined;
};
/**
 * Helper to get staff member name from time slots by ID
 * @internal - exported for testing
 */
export const getStaffName = (staffMemberId, slots) => {
    return (slots
        .flatMap((slot) => slot.availableResources[0].resources)
        .find((r) => r._id === staffMemberId)?.name ?? undefined);
};
// ============================================================================
// Service Implementation
// ============================================================================
export const TimeSlotListService = implementService.withConfig()(TimeSlotListServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    const bookingService = getService(BookingServiceDefinition);
    const timeSlotsSignal = signalsService.signal(config.timeSlots || []);
    const isLoadingSignal = signalsService.signal(false);
    const errorSignal = signalsService.signal(null);
    const hasMoreSignal = signalsService.signal(false);
    const viewModeSignal = signalsService.signal(ViewMode.CLASSIC);
    const dateRangeSignal = signalsService.signal({
        start: config.startDate,
        end: config.endDate,
    });
    const cursorSignal = signalsService.signal(undefined);
    const preSelectedStaffMemberIdSignal = signalsService.computed(() => {
        const serviceSelections = bookingService.serviceSelections.get();
        return serviceSelections.length
            ? (serviceSelections[0]?.resources?.[0]?._id ?? undefined)
            : undefined;
    });
    const getServices = () => {
        const serviceSelections = bookingService.serviceSelections.peek();
        return serviceSelections.length
            ? serviceSelections.map((s) => s.service)
            : (config.services ?? []);
    };
    const getFilters = () => {
        const baseFilters = config.filters ?? {};
        const selectedLocation = bookingService.location.peek();
        const isCustomOrCustomerLocation = selectedLocation?.type === LocationType.CUSTOM ||
            selectedLocation?.type === LocationType.CUSTOMER;
        const location = selectedLocation
            ? {
                id: isCustomOrCustomerLocation ? undefined : selectedLocation._id,
                locationType: selectedLocation.type,
            }
            : baseFilters.location;
        const staffMemberIds = preSelectedStaffMemberIdSignal.peek()
            ? [preSelectedStaffMemberIdSignal.peek()]
            : baseFilters.staffMemberIds;
        return { ...baseFilters, location, staffMemberIds };
    };
    const fetchTimeSlots = async () => {
        isLoadingSignal.set(true);
        errorSignal.set(null);
        cursorSignal.set(undefined);
        timeSlotsSignal.set([]);
        try {
            const response = await fetchAvailability({
                services: getServices(),
                timeZone: bookingService.timezone.peek(),
                viewMode: viewModeSignal.peek(),
                fromLocalDate: dateRangeSignal.peek().start,
                toLocalDate: dateRangeSignal.peek().end,
                ...getFilters(),
            });
            timeSlotsSignal.set(response.timeSlots);
            const nextCursor = response.cursorPagingMetadata?.cursors?.next ?? undefined;
            cursorSignal.set(nextCursor);
            hasMoreSignal.set(!!nextCursor);
        }
        catch (error) {
            const message = error instanceof Error
                ? error.message
                : 'Failed to load time slots';
            errorSignal.set(message);
        }
        finally {
            isLoadingSignal.set(false);
        }
    };
    /**
     * Action: Select a time slot
     * Writes selection directly into BookingService (TimeSlotList does not track selection state)
     * - Always sets booking location from slot.location (one location per slot)
     * - Auto-selects staff only when there is exactly one staff option in this slot
     */
    const selectSlot = (slot) => {
        const resources = preSelectedStaffMemberIdSignal.peek()
            ? [
                {
                    _id: preSelectedStaffMemberIdSignal.peek(),
                    name: getStaffName(preSelectedStaffMemberIdSignal.peek(), timeSlotsSignal.peek()),
                },
            ]
            : [];
        const timeSlot = {
            startDate: slot.localStartDate,
            endDate: slot.localEndDate,
            totalCapacity: slot.totalCapacity ?? undefined,
            remainingCapacity: slot.remainingCapacity ?? undefined,
            scheduleId: slot.scheduleId ?? undefined,
            eventInfo: slot.eventInfo,
            location: slot.location,
            resources,
        };
        bookingService.actions.updateItem({
            timeSlot,
        });
    };
    /**
     * Action: Select a staff member for the current slot
     * Updates the booking service with the selected resource
     */
    const selectStaffMember = (staffMemberId) => {
        const selectedTimeSlot = bookingService.serviceSelections.peek()[0]?.timeSlot;
        if (!selectedTimeSlot)
            return;
        const resources = [
            {
                _id: staffMemberId,
                name: getStaffName(staffMemberId, timeSlotsSignal.peek()),
            },
        ];
        bookingService.actions.updateItem({
            timeSlot: {
                ...selectedTimeSlot,
                resources,
            },
        });
    };
    /**
     * Action: Clear staff selection while keeping the selected time slot
     */
    const clearStaffSelection = () => {
        const selectedTimeSlot = bookingService.serviceSelections.peek()[0]?.timeSlot;
        if (!selectedTimeSlot)
            return;
        bookingService.actions.updateItem({
            timeSlot: { ...selectedTimeSlot, resources: [] },
        });
    };
    /**
     * Action: Load more slots (pagination)
     */
    const loadMore = async () => {
        const cursor = cursorSignal.peek();
        if (!cursor) {
            return;
        }
        isLoadingSignal.set(true);
        errorSignal.set(null);
        try {
            const response = await fetchAvailability({
                services: getServices(),
                fromLocalDate: dateRangeSignal.peek().start,
                toLocalDate: dateRangeSignal.peek().end,
                timeZone: bookingService.timezone.peek(),
                viewMode: viewModeSignal.peek(),
                cursor,
                ...getFilters(),
            });
            const newSlots = response.timeSlots;
            timeSlotsSignal.set([...timeSlotsSignal.peek(), ...newSlots]);
            const nextCursor = response.cursorPagingMetadata?.cursors?.next ?? undefined;
            cursorSignal.set(nextCursor);
            hasMoreSignal.set(!!nextCursor);
        }
        catch (error) {
            const message = error instanceof Error
                ? error.message
                : 'Failed to load more time slots';
            errorSignal.set(message);
        }
        finally {
            isLoadingSignal.set(false);
        }
    };
    /**
     * Action: Update date range (effect will handle refetch)
     */
    const setDateRange = (newStartDate, newEndDate) => {
        const { start: currentStartDate, end: currentEndDate } = dateRangeSignal.peek();
        if (currentStartDate.getTime() === newStartDate.getTime() &&
            currentEndDate.getTime() === newEndDate.getTime()) {
            return;
        }
        dateRangeSignal.set({ start: newStartDate, end: newEndDate });
    };
    let isFirstRun = true;
    signalsService.effect(() => {
        dateRangeSignal.get();
        bookingService.timezone.get();
        bookingService.location.get();
        preSelectedStaffMemberIdSignal.get();
        if (isFirstRun) {
            isFirstRun = false;
            if (config.timeSlots) {
                return;
            }
        }
        fetchTimeSlots();
    });
    return {
        timeSlots: timeSlotsSignal,
        isLoading: isLoadingSignal,
        error: errorSignal,
        hasMore: hasMoreSignal,
        dateRange: dateRangeSignal,
        actions: {
            selectSlot,
            selectStaffMember,
            clearStaffSelection,
            loadMore,
            setDateRange,
        },
    };
});
/**
 * SSR Loader: Pre-fetches time slots for server-side rendering
 * Use this in Astro/Next.js getServerSideProps or page loaders
 *
 * @example
 * ```typescript
 * // In Astro page
 * const loadResult = await loadTimeSlotListConfig({
 *   services: bookingServices,
 *   startDate: new Date(),
 *   endDate: addDays(new Date(), 7),
 *   timezone: 'America/New_York',
 * });
 *
 * if (loadResult.type === 'error') {
 *   // Handle error
 * }
 *
 * const timeSlotListConfig = loadResult.config;
 * ```
 */
export async function loadTimeSlotListConfig(options) {
    try {
        const response = await fetchAvailability({
            services: options.services || [],
            fromLocalDate: options.startDate,
            toLocalDate: options.endDate,
            timeZone: options.timezone ?? getClientTimezone(),
            ...options.filters,
        });
        const config = {
            ...options,
            timeSlots: response.timeSlots || [],
        };
        return { type: 'success', config };
    }
    catch (error) {
        const message = error instanceof Error ? error.message : 'Failed to load time slots';
        return { type: 'error', error: message };
    }
}
